window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-ulceras-genitais"]={"block":"anki:ginecologia-ulceras-genitais","label":"Anki · Úlceras Genitais","count":40,"questions":[{"id":"anki-ginecologia-ulceras-genitais-c005b1a03dbb2fad","number":"0201w","sourceNumber":"0201w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Uma mulher de 25 anos de idade procurou atendimento com queixa de lesão vulvar há uma semana. Refere ter tido relação desprotegida recentemente. Nega doenças crônicas, febre ou qualquer outro sintoma associado. Ao exame, presença de úlcera única em pequeno lábio à direita, indolor, com bordos endurecidos e fundo limpo, e linfonodomegalia inguinal bilateral, de caráter inflamatório. Com base nesse caso hipotético, assinale a alternativa que apresenta, respectivamente, o diagnóstico e o exame por meio do qual ele pode ser confirmado.","options":{"A":"herpes genital e pesquisa de herpes vírus simples por técnica de biologia molecular","B":"cancro duro e exame em campo escuro","C":"cancro mole e exame bacterioscópico","D":"linfogranuloma venéreo e cultura com células de McCoy","E":"donovanose e citopatologia para identificação dos corpúsculos de Donovan"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera única, sem dor, com bordas endurecidas e limpa por dentro, junto com gânglios inflamados dos dois lados da virilha — é o retrato clássico do cancro duro, a lesão da sífilis primária. O exame que confirma é o campo escuro, que consegue visualizar diretamente a bactéria (Treponema pallidum) retirada da lesão.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432176","ankiGuid":"Fv&:G@w@{}"},{"id":"anki-ginecologia-ulceras-genitais-73794be731df44a9","number":"0202w","sourceNumber":"0202w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 18 anos de idade refere que estava assintomática até 5 dias atrás, quando notou aparecimento de ferida de 2 cm na vulva. Refere que se relaciona sexualmente com outras mulheres. Segundo o Ministério da Saúde, deve-se:","options":{"A":"biopsiar a borda da úlcera antes de indicar tratamento.","B":"coletar sorologias para infeções sexualmente transmissíveis para orientar o tratamento.","C":"coletar material da úlcera para exame a fresco para orientar o tratamento.","D":"medicar com aciclovir por via oral e tópica.","E":"medicar a paciente com penicilina e azitromicina."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Quando não dá pra confirmar rapidinho qual é a causa exata de uma úlcera genital (por falta de exames), o Ministério da Saúde recomenda tratar 'às cegas' pelas causas mais prováveis e perigosas ao mesmo tempo — nesse caso, penicilina (cobre sífilis) e azitromicina (cobre cancro mole) — em vez de esperar o resultado de exames que podem demorar ou nunca serem feitos.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432177","ankiGuid":"J-:P-/:NC?"},{"id":"anki-ginecologia-ulceras-genitais-0f74dd9e5f7ecdf1","number":"0203w","sourceNumber":"0203w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente refere que há um dia notou úlcera genital dolorosa, e que hoje apareceram outras lesões também dolorosas. Ao exame observam-se úlceras dolorosas nos lábios, de fundo sujo e bordas sobrelevadas, em espelho. O diagnóstico provável e o tratamento são, respectivamente?","options":{"A":"sífilis primária, penicilina procaína 1.200.000 UI IM.","B":"cancro mole, ceftriaxone 250mg IM.","C":"herpes genital, aitromicina 1000mg VO.","D":"linfogranuloma venéreo, ciprofloxacina 500mg VO."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlceras dolorosas, que aparecem 'em espelho' (uma de cada lado, porque a lesão se toca e se contamina), com fundo sujo e bordas elevadas — é o retrato clássico do cancro mole, causado pela bactéria Haemophilus ducreyi. O tratamento é com ceftriaxona.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432178","ankiGuid":"gi8}zVw%f8"},{"id":"anki-ginecologia-ulceras-genitais-6bf1335adf8e34a2","number":"0204w","sourceNumber":"0204w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 40 anos refere dor vulvar intensa há 2 dias, com o seguinte achado clínico:\n\nQual é o tratamento adequado?","options":{"A":"Ceftriaxone.","B":"Valaciclovir.","C":"Clotrimazol.","D":"Penicilina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":["question_bank/media/ginecologia-ulceras-genitais/paste-4e4ab61d2eca42d75fb401f5bd8c5aad07e320f7.png"],"optionImages":{},"commentImages":[],"comment":"Dor vulvar intensa e recente, com o achado clínico mostrado na imagem (provavelmente vesículas agrupadas) — sugerindo herpes genital. O tratamento é com um antiviral, como o valaciclovir.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432179","ankiGuid":"Hm&>EsZXUP"},{"id":"anki-ginecologia-ulceras-genitais-1238d96c5acdae46","number":"0205w","sourceNumber":"0205w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Fase de inoculação do Linfogranuloma venéreo (LGV) inicia-se por pápula, pústula ou exulceração indolor, que desaparece sem deixar sequela. Somente podemos indicar como errado o item:","options":{"A":"Muitas vezes, não é notada pelo paciente.","B":"Raramente é observada pelo profissional de saúde.","C":"Localiza-se, no homem, no sulco coronal, frênulo e nunca no prepúcio.","D":"Localiza-se na mulher, na parede vaginal posterior, colo uterino, fúrcula e outras partes da genitália externa."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a C: no homem, a lesão inicial do linfogranuloma venéreo PODE sim aparecer no prepúcio — dizer que 'nunca' acontece ali está errado, já que essa lesão pode surgir em qualquer parte da genitália exposta ao contato sexual. As outras frases (sobre ela passar despercebida, ser raramente vista pelo profissional, e a localização na mulher) estão corretas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432180","ankiGuid":"qx~N}A/aPh"},{"id":"anki-ginecologia-ulceras-genitais-5b88c5deed05bfb6","number":"0206w","sourceNumber":"0206w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"As úlceras genitais representam síndrome clínica, sendo muitas vezes causadas por IST, e se manifestam como lesões ulcerativas, precedidas ou não por pústulas e/ou vesículas, acompanhadas ou não de dor, ardor, prurido, drenagem de material mucopurulento, sangramento e linfadenopatia regional. Assinale a alternativa ERRADA.","options":{"A":"O cancróide é uma afecção provocada pelo Haemophilus ducrey. O período de incubação é, geralmente de 03 a 05 dias. Manifesta-se por lesões dolorosas, podendo ser múltiplas e de fundo heterogêneo, recoberto por exsudado necrótico.","B":"O linfogranuloma venéreo tem como manifestação clínica mais comum a linfadenopatia inguinal e/ou femoral.","C":"A pesquisa direta do Treponema pallidum por microscopia pode ser feita de três formas: imunofluorescência direta, técnica com material corado e campo escuro, sendo este último o mais comumente utilizado pelo SUS.","D":"O primeiro episódio de herpes genital poderia ser tratado com aciclovir 200mg, 2 comprimidos, VO, 3x/d, por 7 a 10 dias, mesmo em gestante em qualquer trimestre da gestação.","E":"A donovanose é uma IST causada pela bactéria Klebsiella granulomatis, acomete principalmente os homens. As lesões são dolorosas, geralmente múltiplas. No homem as localizações mais frequentes são no frênulo e sulco bálano-prepucial. A localização extragenital é comum e quase sempre ocorre a partir de lesões genitais."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a E: as lesões da donovanose são classicamente INDOLORES (sem dor), não dolorosas como a frase afirma — esse é um dos detalhes que ajuda a diferenciar a donovanose do cancro mole (que sim é doloroso). As outras frases (sobre o cancroide, o linfogranuloma venéreo, o exame de campo escuro pra sífilis, e o tratamento do herpes mesmo em gestantes) estão corretas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432181","ankiGuid":"E1xuZ&igl."},{"id":"anki-ginecologia-ulceras-genitais-0b540eb9a8b2e602","number":"0207w","sourceNumber":"0207w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Sobre a sífilis, assinale a alternativa INCORRETA.","options":{"A":"A penicilina é o único fármaco efetivo para prevenir a transmissão materno-fetal etratar a infecção fetal.","B":"Sempre se deve tratar o parceiro, mesmo que sorologicamente negativo.","C":"Na fase primária, caracteriza-se por úlcera dolorosa e múltipla.","D":"FTA-ABS é o teste padrão-ouro entre os testes treponêmicos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a C: a lesão da sífilis primária (o cancro duro) é classicamente ÚNICA e INDOLOR — dizer que é 'dolorosa e múltipla' está errado, e essa é justamente uma das características que ajuda a diferenciar da sífilis de outras causas de úlcera genital (como o cancro mole, que sim é doloroso). As outras frases (penicilina como único tratamento eficaz na gravidez, tratar sempre o parceiro, e o FTA-ABS como padrão-ouro) estão corretas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432182","ankiGuid":"h`wXT@y9se"},{"id":"anki-ginecologia-ulceras-genitais-c88a558d167c7948","number":"0208w","sourceNumber":"0208w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Úlceras genitais (UG) são lesões localizadas na vulva, vagina ou colo uterino com perda de tecido, envolvendo a epiderme e a derme ou apenas a epiderme. Três mulheres com vida sexual ativa são atendidas, referindo úlcera genital: - Maria, 22 anos: o quadro é recorrente e iniciado por hiperemia vulvar seguida do surgimento de vesículas agrupadas que, após, rompem-se formando exulceração dolorosa, seguida de resolução sem deixar marcas. - Joana, 19 anos: observa-se a presença de lesão única com bordas endurecidas em intróito vaginal. Além da úlcera observa-se adenopatia bilateral (inguinal), indolor e não inflamatória; - Antônia, 24 anos: inicialmente surgiram três lesões nodulares que evoluíram para úlcera não dolorosa e altamente vascularizada, sangrando facilmente com o contato; Com base no quadro clínico das pacientes a principal hipótese diagnóstica dentre as opções abaixo para Maria, Joana e Antônia respectivamente são:","options":{"A":"herpes genital, sífilis primária e donovanose","B":"donovanose, sífilis primária e herpes genital","C":"herpes genital, cancro mole e donovanose","D":"cancro mole, donovanose e herpes genital","E":"sífilis primária, donovanose e herpes genital"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Maria (vesículas que rompem formando úlcera dolorosa, que cicatriza sem marcas, e volta a acontecer) tem herpes genital. Joana (úlcera única, bordas endurecidas, gânglios indolores dos dois lados) tem sífilis primária (o cancro duro). Antônia (lesões que crescem, sangram fácil e não doem) tem donovanose, uma infecção que causa tecido bem vascularizado que sangra com facilidade.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432183","ankiGuid":"vpwDMU!=Ib"},{"id":"anki-ginecologia-ulceras-genitais-144b63594a37f5e8","number":"0209w","sourceNumber":"0209w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Adolescente de 15 anos, feminino, procura Unidade Básica de Saúde com queixa de ferida em vulva há 7 dias. Relata sexarca aos 13 anos, 5 parcerias sexuais nos últimos 6 meses e não usa preservativos. Faz uso regular de anticonceptivo hormonal injetável; última menstruação há 15 dias. Exame físico da região genital: presença de úlcera indolor, endurecida, sem secreção em grande lábio esquerdo. Linfonodos inguinais palpáveis, fibroelásticos, móveis indolores, o maior medindo 2,0 x 2,0cm. Não há disponibilidade para a realização de exame bacterioscópico da lesão. Qual a conduta mais adequada para o caso?","options":{"A":"Doxiciclina 100mg, 12/12h por 21 dias + aciclovir 200mg 5x/dia por 7 dias.","B":"Benzilpenicilina benzatina 2,4 milhões de UI IM, dose única + aciclovir 200mg 5x/dia por 7 dias.","C":"Azitromicina 500mg, 2 comprimidos dose única + doxiciclina 100mg, 12/12h por 21 dias.","D":"Azitromicina 500mg, 2 comprimidos dose única + benzilpenicilina benzatina 2,4 milhões de UI IM, dose única.","E":"Benzilpenicilina benzatina 2,4 milhões de UI IM, Semanal, por 3 semanas"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera indolor e endurecida, com gânglios firmes e indolores na virilha — quadro clássico de cancro duro (sífilis primária). Sem poder confirmar com exame, a conduta padrão do Ministério da Saúde é tratar tanto sífilis (com penicilina) quanto cancro mole (com azitromicina) ao mesmo tempo, já que os dois são possibilidades e o tratamento precoce evita complicações e a transmissão.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432184","ankiGuid":"tQL(/0lx`P"},{"id":"anki-ginecologia-ulceras-genitais-658b1c7c8e98da6e","number":"0210w","sourceNumber":"0210w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"A infecção pelos vírus da herpes simples tipos 1 e 2 é extremamente comum em mulheres na idade fértil. Estima-se que sua prevalência aproxime-se de 70% em gestantes. Sobre a infecção fetal por essa patologia, assinale a alternativa correta.","options":{"A":"Geralmente, é fatal na infecção materna ativa em qualquer idade gestacional.","B":"Quanto maiores os sintomas maternos, maior o risco de transmissão para o feto.","C":"A infecção primária materna correlaciona-se com maiores riscos de infecção fetal.","D":"A indicação da via de parto será cesariana em caso de lesões ativas, independentemente do local das lesões.","E":"Em casos de reativação da infecção materna, maior será o risco de transmissão vertical comparada à primoinfecção."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Quando a mãe pega herpes genital PELA PRIMEIRA VEZ durante a gravidez (infecção primária, sem ter anticorpos prévios pra passar pro bebê), o risco de transmitir a infecção pro feto é bem maior do que quando é só uma reativação de uma infecção antiga (já que, nesse caso, a mãe já tem anticorpos protetores que ajudam a proteger o bebê também).","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432185","ankiGuid":"FX**z]zdX<"},{"id":"anki-ginecologia-ulceras-genitais-7e8ec372cd31ccfe","number":"0211w","sourceNumber":"0211w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"O linfogranuloma venéreo (LGV) é uma doença infecciosa sistêmica e crônica cujos principais efeitos resultam em dano ao sistema linfático de drenagem da infecção. Analise as assertivas sobre o tema. I. O agente etiológico é Calmmatobacterium granulomatis. II. O agente etiológico é a Chlamydia trachomatis. III. Também denominada de linfogranuloma inguinal e doença de Nicolas-Favre-Durand. IV. O agente etiológico é o Haemophilus ducreyi. Está CORRETO o que se afirma em:","options":{"A":"I, II, III e IV.","B":"II e III, apenas.","C":"III e IV, apenas.","D":"II e III, apenas.","E":"IV, apenas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A (todas corretas), mas isso está errado — os itens I e IV descrevem os agentes ERRADOS. O item I (Calymmatobacterium granulomatis) é na verdade o agente da DONOVANOSE, não do LGV. O item IV (Haemophilus ducreyi) é o agente do CANCRO MOLE, não do LGV. O verdadeiro agente do linfogranuloma venéreo é a Chlamydia trachomatis (item II, correto), e ele também é conhecido como doença de Nicolas-Favre-Durand (item III, correto). Por isso, a resposta certa é apenas II e III.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432186","ankiGuid":"i`3=VCKlPR"},{"id":"anki-ginecologia-ulceras-genitais-4adc7192c28d0a97","number":"0212w","sourceNumber":"0212w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Uma paciente de vinte e cinco anos de idade consultou-se com ginecologista por apresentar lesão vulvar que, segundo ela, havia surgido cerca de seis dias após uma relação sexual desprotegida. No exame físico, ela apresentava lesão ulcerada localizada na face interna dos grandes lábios, dolorosa, sangrante, com bordas irregulares, eritematosas, com fundo purulento e de odor fétido. Considerando o precedente caso clínico, julgue o item subsecutivo. O debridamento cirúrgico de úlceras vulvares de origem infecciosa melhora a eficácia do tratamento antimicrobiano.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase está errada: retirar tecido cirurgicamente (debridamento) não melhora a eficácia do tratamento com antibiótico nas úlceras genitais infecciosas — o tratamento é feito com o remédio certo pra cada agente, sem necessidade de intervenção cirúrgica na maioria dos casos.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432187","ankiGuid":"j~{zy;/w`#"},{"id":"anki-ginecologia-ulceras-genitais-441a78726ff81a8e","number":"0213w","sourceNumber":"0213w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Os aspectos clínicos das úlceras genitais são bastante variados e têm baixa relação de sensibilidade e especificidade com o agente etiológico, mesmo nos casos considerados clássicos. Sendo inadequado que:","options":{"A":"o diagnóstico com base na impressão clínica apresentou valores preditivos positivos muito baixos – 30,9% para sífilis e 32,7% para cancroide – por ocasião do estudo de validação da abordagem sindrômica no Brasil.","B":"a úlcera genital está frequentemente associada às IST na população sexualmente ativa.","C":"ocorre associação em particular nos adolescentes e adultos jovens, a queixa de úlcera genital não é exclusividade das ISTs.","D":"em pelo menos 45% dos pacientes com úlcera genital não há confirmação laboratorial do agente etiológico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"As úlceras genitais são difíceis de diagnosticar só pela aparência — mesmo em casos considerados 'clássicos', a impressão clínica sozinha erra bastante (valores preditivos baixos, como mostrado nos estudos brasileiros), e nem sempre a causa é confirmada em laboratório, o que reforça a importância de uma abordagem mais ampla (sindrômica) no tratamento inicial.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432188","ankiGuid":"kq.u_,4oO}"},{"id":"anki-ginecologia-ulceras-genitais-735ef2d72287f341","number":"0214w","sourceNumber":"0214w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Linfogranuloma venéreo e granuloma inguinal (donovanose) devem ser tratados com:","options":{"A":"Doxiciclina 100 mg. VO, a cada 12h, por no mínimo três semanas.","B":"Tetraciclina 50 mg, VO, a cada 8h, por no mínimo três semanas.","C":"Cefalexina 500 mg, VO, a cada 12h, por no mínimo duas semanas.","D":"Azitromicina, 1 g, VO, uma vez ao dia, por no mínimo duas semanas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Tanto o linfogranuloma venéreo quanto a donovanose (granuloma inguinal) precisam de tratamento prolongado — a doxiciclina, tomada por pelo menos três semanas (ou até a lesão sumir completamente), é a primeira escolha pra essas duas condições.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432189","ankiGuid":"AnDxF3vy2S"},{"id":"anki-ginecologia-ulceras-genitais-bed3f7f174bbb96d","number":"0216w","sourceNumber":"0216w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 23 anos procura unidade básica de saúde apresenta úlcera genital com evolução de 3 dias , sem história prévia de vesículas. Tem vida sexual ativa e não possui o hábito de usar preservativos. Considerando que não há possibilidade de solicitação de exames laboratoriais , nem garantia de retorno da paciente ao ambulatório, qual seria a melhor conduta?","options":{"A":"Aciclovir 200 mg 2 cp via oral 8/8 h por 5 dias + penicilina G Benzatina 2,4 milhões de unidades dose única intramuscular.","B":"Azitromicina 500 mg 2 cp via oral em dose única + Penicilina G Benzatina 2,4 milhões de unidades dose única intramuscular.","C":"Doxicilina 100 mg 1 cp Vo 12/12h por 21 dias + Penicilina G Benzatina 2,4 milhões de unidades (IM) uma vez por semana por 3 semanas.","D":"Penicilina G Benzatina 2,4 milhões de unidades (im) em dose única.","E":"Azitromicina 500 mg 2 cp dose única + Penicilina G Benzatina 2,4 milhões de unidades (IM) uma vez por semana por 3 semanas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera recente, sem histórico de vesículas antes, sem exames disponíveis e sem garantia de retorno da paciente — a conduta certa é o tratamento sindrômico recomendado pelo Ministério da Saúde: cobrir ao mesmo tempo cancro mole (azitromicina) e sífilis (penicilina), já que são as causas mais prováveis e perigosas de se deixar passar.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432191","ankiGuid":"rL;1reIc8P"},{"id":"anki-ginecologia-ulceras-genitais-f629e15669b16497","number":"0217w","sourceNumber":"0217w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Assinale a correlação verdadeira, relativa a ISTs:","options":{"A":"Herpes: úlcera vulvar profunda dolorosa, células coilocitóticas.","B":"Linfogranuloma venéreo: retites estenosantes e elefantíase genital.","C":"Cancro mole: úlcera vulvar indolor e de fundo limpo.","D":"Sífilis: úlceras rasas, dolorosas, múltiplas, com borda amolecida e bem delimitada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O linfogranuloma venéreo, quando não tratado a tempo, pode evoluir com complicações crônicas graves: estreitamento do reto (retite estenosante) e elefantíase genital (inchaço permanente por obstrução dos vasos linfáticos) — complicações que mostram como essa infecção, se negligenciada, pode causar dano duradouro.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432192","ankiGuid":"J%{g|!dyFs"},{"id":"anki-ginecologia-ulceras-genitais-8569f3c49ce94305","number":"0218w","sourceNumber":"0218w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Assinale a alternativa correta quanto ao diagnóstico das infecções sexualmente transmissíveis. I. A lesão clínica inicia-se como uma pápula ou vesículas que progride rapidamente para uma ou múltiplas úlceras, dolorosas, com base amolecida e fundo purulento. II. Inicia-se com lesão nodular, indolor, única ou múltipla, subcutânea, que pode erosar e produzir ulceração de crescimento lento e sangrante. III. Inicia-se pela presença de úlcera única, de fundo liso e limpo, indolor e endurecida. O quadro clínico corresponde, respectivamente à:","options":{"A":"Cancro Mole; Donovanose e Sífilis Primária.","B":"Sífilis Secundária, Molusco Contagioso, Linfogranuloma venéreo.","C":"Gonococcia, Bartholinite, Cancro Duro.","D":"Condilomatose, Citomegalovirose, Líquen escleroso."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Item I (pápula que vira úlceras dolorosas, com base amolecida, fundo purulento) = cancro mole. Item II (lesão nodular indolor que ulcera e cresce devagar, sangrando) = donovanose. Item III (úlcera única, fundo liso e limpo, indolor e endurecida) = sífilis primária (cancro duro). Cada descrição bate com o padrão clássico de cada doença.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432193","ankiGuid":"Q%rmR-%Vd."},{"id":"anki-ginecologia-ulceras-genitais-4fb8d89caa89963d","number":"0219w","sourceNumber":"0219w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente, 24 anos, procura assistência médica devido a uma \"ferida\" na região vulvar. Refere ser dolorosa e surgiu há 5 dias. Nega prurido. São afirmativas corretas, exceto:","options":{"A":"O diagnóstico sindrômico de úlcera genital é preconizado no SUS.","B":"É importante sempre definir o diagnóstico clínico de herpes na abordagem inicial.","C":"Sorologias para DST sempre devem ser oferecidas.","D":"Clinicamente seria compatível com sífilis primária.","E":"A lesão pode ser compatível com cancro mole."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase errada é a D: uma úlcera DOLOROSA (como a descrita nessa paciente) não é compatível com sífilis primária, que classicamente causa uma úlcera INDOLOR — por isso essa hipótese não se encaixa bem no caso. As outras frases (sobre o diagnóstico sindrômico do SUS, a importância de considerar herpes, oferecer sorologias, e a possibilidade de cancro mole) estão corretas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432194","ankiGuid":"siZIG$*}PM"},{"id":"anki-ginecologia-ulceras-genitais-18b0736958f0597e","number":"0220w","sourceNumber":"0220w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Correlacione os itens e assinale a alternativa correta. 1. Rash maculopapular que pode envolver todo o corpo e inclui palmas das mãos, as solas dos pés e as mucosas; 2. Úlcera isolada, firme ao toque, com bordas arredondadas levemente elevadas e base não infectada; 3. Nódulos inflamatórios indolores, que evoluem para úlceras avermelhadas e friáveis, que cicatrizam por fibrose e resultam em cicatrizes; 4. Vesícula dolorosa que evolui para ulceração e formação de crosta; 5. Uma ou várias pápulas com umbilicação central. I. Molluscum contagiosum; II. Sífilis primária; III. Donovanose; IV. Herpes; V. Sífilis secundária. A sequência correta é:","options":{"A":"1-II / 2-V / 3-I / 4-IV / 5-III.","B":"1-II / 2-V / 3-III / 4-IV / 5-I.","C":"1-V / 2-II / 3-III / 4-IV / 5-I.","D":"1-V / 2-II / 3-I / 4-IV / 5-III.","E":"1-I / 2-III / 3-II / 4-V / 5-IV."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Cada descrição bate com uma doença: manchas por todo o corpo incluindo palmas e plantas = sífilis SECUNDÁRIA (fase mais avançada, diferente do cancro duro da primária); úlcera única e firme = sífilis primária; nódulos que viram úlceras e cicatrizam com fibrose = donovanose; vesícula dolorosa que vira crosta = herpes; pápulas com 'covinha' no meio = molusco contagioso (um vírus de pele, nem sempre sexualmente transmitido, mas que pode aparecer na região genital).","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432195","ankiGuid":"MUlA+1l%{A"},{"id":"anki-ginecologia-ulceras-genitais-03a6708dc70bd503","number":"0222w","sourceNumber":"0222w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 18 anos procurou serviço médico em pronto atendimento de sua região com queixa de dor, que fica intensa quando urina (contato da urina com as lesões), queimação vaginal e coceira. Há 10 dias percebeu umas \"bolinhas\" (vesículas) em suas partes intimas. Relata ter ido ao médico da UBS e foi prescrito uma pomada que usou por sete dias sem melhora. Foi questionada se já havia apresentado esse quadro anteriormente e respondeu que essa era a primeira vez que apresentava essa queixa. Menarca aos 11 anos, vida sexual ativa desde os 13 anos com um total de oito parceiros até o momento. Informou ainda que fez um tratamento para verruga genital há 2 anos quando estava grávida. Há dois dias acabou o seu namoro. Marque a alternativa incorreta:","options":{"A":"O diagnóstico desse caso é herpes genital primo-infecção. Pode ser tratado com valaciclovir 500 mg via oral de 12 em 12 horas, por cinco dias, 1g dose única diária, por cindo dias","B":"Nos EUA, país que tem várias pesquisas, a maioria das mulheres com úlceras genitais tem infecção pelo Herpes Simples Viral (HSV) ou sífilis e o cancroide é a teceira causa mais comum de úlceras genitais.","C":"A primo-infecção ocorre entre quatro a sete dias após a exposição, em indivíduos não expostos previamente ao herpes-vírus.","D":"No HSV primo-infecção nem todos os expostos desenvolverão manifestação clínica exuberante, podendo haver infecção subclínica com evolução para a fase de portador."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A frase incorreta é a A: a descrição da dose de valaciclovir está confusa e mistura dois esquemas diferentes de forma incoerente ('12/12h por 5 dias' e '1g dose única diária por 5 dias' ao mesmo tempo) — um erro na forma como a dose foi descrita. As outras frases (sobre a frequência de herpes/sífilis como causas de úlcera genital nos EUA, o tempo de incubação da primo-infecção, e a possibilidade de infecção subclínica sem sintomas visíveis) estão corretas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432197","ankiGuid":"uQ*e$OV-^_"},{"id":"anki-ginecologia-ulceras-genitais-f1e8dce85f86d6f6","number":"0223w","sourceNumber":"0223w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Sobre o cancro mole, é CORRETO afirmar que:","options":{"A":"É causada por um bacilo sem motilidade, não formador de esporos, facultativo, Gram- positivo, o Haemophilus ducreyi.","B":"Em geral, o período de incubação é de 3 a 10 semanas, e o acesso ao hospedeiro requer a presença de fissura na pele ou na mucosa.","C":"Causa reação sistêmica exuberante com síndrome prodrômica descrita.","D":"Inicia como pápula eritematosa que evolui para pústula, sofrendo ulceração em 48 horas. Em geral, as lesões são recobertas com material purulento.","E":"Linfadenopatia inguinal mole unilateral ou bilateral é infrequente."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O cancro mole começa como uma mancha avermelhada (pápula) que rapidamente vira uma bolha de pus (pústula) e forma uma úlcera dentro de 48 horas — as lesões costumam ficar cobertas por um material purulento (pus), diferente do cancro duro da sífilis, que tem fundo limpo.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432198","ankiGuid":"y6yI21JG2M"},{"id":"anki-ginecologia-ulceras-genitais-012888c2daeaae14","number":"0224w","sourceNumber":"0224w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Mulher de 40 anos de idade vem para consulta na unidade básica de saúde por dor na região genital há dois dias. É solteira, não tem parceiro fixo, mas tem vida sexual ativa. Nega outros antecedentes mórbidos relevantes. No exame clínico é feito o diagnóstico de primoinfecção herpética. Além do tratamento medicamentoso para a paciente, qual é a conduta para o caso?","options":{"A":"Esclarecer as formas de transmissão e orientar a comunicação aos seus parceiros sexuais para diagnóstico e tratamento.","B":"Evitar revelar aos parceiros a transmissão sexual da doença, pela incerteza do contágio sexual.","C":"Evitar revelar aos parceiros a transmissão sexual da doença pelo risco de violência contra a paciente.","D":"Prescrever o mesmo tratamento medicamentoso para o seu parceiro atual."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Quando uma pessoa descobre que tem herpes genital (ou qualquer IST), é importante explicar como a doença é transmitida e orientar que ela avise seus parceiros sexuais, pra que eles também possam ser avaliados e tratados se necessário — é uma parte essencial do cuidado, não só medicamentoso.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432199","ankiGuid":"bYcRR`6Q.v"},{"id":"anki-ginecologia-ulceras-genitais-a9a9d6c98f6c8a31","number":"0225w","sourceNumber":"0225w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"O cancro mole, cancro venéreo simples ou cancro de Ducrey é uma afecção provocada pelo Haemophilus ducrey. Caracteriza-se por lesões em geral múltiplas ou única, que são dolorosas e têm aspecto purulento. Quanto ao seu tratamento, são várias as opções. O medicamento que NÃO deve ser utilizado para o tratamento do cancro é","options":{"A":"Ciprofloxacina 500 mg, VO, dose única.","B":"Ceftriaxona 250 mg, IM, dose única.","C":"Azitromicina 1 g, VO, dose única.","D":"Tianfenicol 5,0 g, VO, dose única."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A ciprofloxacina em DOSE ÚNICA não é o jeito certo de usá-la contra o cancro mole — quando esse remédio é usado, precisa ser em várias doses ao longo de alguns dias (não uma dose só), diferente da azitromicina ou ceftriaxona, que realmente funcionam em dose única.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432200","ankiGuid":"suUddyYZD~"},{"id":"anki-ginecologia-ulceras-genitais-e61d731f4e86c173","number":"0226w","sourceNumber":"0226w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 18 anos vem à consulta com queixa de ferida em genital e conta que teve relação sexual sem uso de preservativo com vários parceiros nos últimos meses. Faz uso correto de contraceptivo hormonal oral combinado. Nega outras doenças ou alergia a medicamentos. Considerando-se as DSTs e o uso do Fluxograma para Manejo de úlcera genital proposto pelo Ministério da Saúde, assinale a alternativa CORRETA.","options":{"A":"Se as lesões durarem mais que 4 semanas, o tratamento é exclusivamente destinado a herpes genital.","B":"Se há evidências ou história de vesículas, o tratamento destina-se a Cancróide e Donovanose.","C":"Considerando-se que há laboratório disponível, recomenda-se coleta de material para microscopia (GRAM e Giemsa) e campo escuro e exames de biologia molecular.","D":"Se os exames laboratoriais sugerirem H. ducrey, deve-se tratar Donovanose.","E":"Se o laboratório for sugestivo de K. granulomatis, o tratamento deve ser dirigido para Cancroide."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Quando há laboratório disponível pra investigar uma úlcera genital, o ideal é coletar material da lesão pra vários exames ao mesmo tempo: microscopia com corantes específicos (Gram e Giemsa), campo escuro (pra sífilis) e testes moleculares mais modernos — assim se aumenta a chance de identificar a causa exata e tratar de forma mais direcionada.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432201","ankiGuid":"QS5THW){VG"},{"id":"anki-ginecologia-ulceras-genitais-64376b484ef35c9d","number":"0227w","sourceNumber":"0227w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"As úlceras genitais representam síndrome clínica produzida por agentes infecciosos sexualmente transmissíveis e que se manifestam como lesões ulcerativas erosivas, precedidas ou não por pústulas e/ou vesículas, acompanhadas ou não de dor, ardor, prurido, drenagem de material mucopurulento, sangramento e linfadenopatia regional. Em aspecto específico, assinale o agente etiológico da donovanose.","options":{"A":"Haemophilus ducrey","B":"Chlamydia trachomatis","C":"HPV","D":"Treponema pallidum","E":"Klebsiela granulomatis"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"A donovanose é causada pela bactéria Klebsiella granulomatis (antes chamada de Calymmatobacterium granulomatis) — uma infecção que causa lesões que crescem devagar e sangram com facilidade.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432202","ankiGuid":"G>o+_W~/vR"},{"id":"anki-ginecologia-ulceras-genitais-6b5a60087c69dfb0","number":"0228w","sourceNumber":"0228w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Adolescente de 17 anos procura atendimento por úlceras, rasas, em região genital externa, dolorosas, com bordas hiperemiadas, irregulares, que surgiram há cerca de uma semana após coito, associadas a linfonodos inguinais ingurgitados e dolorosos, sendo que alguns se mostram como abcessos com flutuação na virilha. Em esfregaço de material das lesões, verificam-se cocobacilos curtos, aos pares, intra e extracelulares, às vezes formando cadeias. O diagnóstico e o tratamento são, respectivamente:","options":{"A":"donovanose - tetraclina 500 mg, via oral, de 6/6 horas, por 15 dias.","B":"cancro mole (Haemophilus ducreyi) - azitromicina, 1 g, em dose única.","C":"sífilis - penicilina benzatínica, 2.400.000 Ul, intramuscular, dose única.","D":"herpes genital - aciclovir 400 mg, duas vezes ao dia, por sete dias."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlceras dolorosas com bordas irregulares e vermelhas, gânglios da virilha inchados e alguns virando abscessos, com o exame mostrando bactérias em pares/cadeias (o padrão clássico 'em cardume de peixes') — é o retrato do cancro mole, causado pelo Haemophilus ducreyi. O tratamento é azitromicina em dose única.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432203","ankiGuid":"ryp$)IIag0"},{"id":"anki-ginecologia-ulceras-genitais-48b5671c187a6be1","number":"0229w","sourceNumber":"0229w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Gestante a termo, com quadro de rotura prematura das membranas há duas horas, sem metrossístoles, feto vivo e líquido amniótico claro com grumos. Ao exame genital, verificam-se lesões herpéticas ativas em borda inferior do introito vaginal. A conduta, neste caso, é:","options":{"A":"indução do trabalho de parto.","B":"cesariana no momento da internação.","C":"espera da entrada espontânea do trabalho de parto por 12 horas.","D":"cesariana após tratamento do herpes genital."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Quando uma grávida está em trabalho de parto (ou com bolsa rota) e tem lesões de herpes ATIVAS na região genital, a conduta é fazer cesariana assim que possível — isso evita que o bebê entre em contato com o vírus durante a passagem pelo canal de parto, o que poderia causar uma infecção neonatal grave.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432204","ankiGuid":"s%H%0g:{PE"},{"id":"anki-ginecologia-ulceras-genitais-d4173f599c5ed316","number":"0230w","sourceNumber":"0230w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"O agente etiológico da doença de transmissão exclusivamente sexual, mais frequente nas regiões tropicais, que se caracteriza por apresentar lesões múltiplas (podendo ser única), tipo úlceras, habitualmente dolorosas, de borda irregular, com contornos eritematoedematosos e fundo irregular, cobertas por exsudato necrótico, amarelado e de odor fétido que, quando removido, revela tecido de granulação que apresenta sangramento fácil quando submetido a traumatismos, ocorrendo na fúrcula e na face interna dos grandes lábios, lesões que produzam sintomatologia discreta no colo uterino e na parede vaginal, lesões extragenitais e infecções assintomáticas é o(a)","options":{"A":"Chlamydia tracomatis.","B":"Calymmatobacterium granulomatis (Klebsiella granulomatis, Donovania granulomatis).","C":"Neisseria gonorrhoeae.","D":"papilomavírus humano.","E":"Haemophilus ducreyi."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Essa descrição (úlceras dolorosas, bordas irregulares, fundo sujo com odor forte, que sangram fácil quando manipuladas) é bem característica do cancro mole, causado pelo Haemophilus ducreyi — uma infecção transmitida exclusivamente por via sexual, mais comum em regiões tropicais.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432205","ankiGuid":"e?c~*w(jhH"},{"id":"anki-ginecologia-ulceras-genitais-9cf7ba8d8804850f","number":"0231w","sourceNumber":"0231w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Gestante no primeiro trimestre apresenta lesões ulceradas em vulva, indolores, acompanhadas de linfonodomegalia inguinal superficial ipsilateral fistulizada e com supuração. Qual o tratamento correto?","options":{"A":"Drenagem incisional com exérese dos linfonodos acometidos.","B":"Doxiciclina 100 mg 12/12h por 14 dias.","C":"Azitromicina 1 g, VO, semanal, por 3 semanas.","D":"Ciprofloxacino 500 mg 12/12h por 10 dias.","E":"Penicilina G benzatina 2.400.000 UI, IM, semanal, por 3 semanas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera indolor com um gânglio da virilha que 'estourou' e está drenando pus — é o quadro clássico do linfogranuloma venéreo (LGV) em fase mais avançada. Como a paciente está grávida (e a doxiciclina, o remédio de escolha normal, é contraindicada na gestação), a alternativa segura é a azitromicina, tomada semanalmente por três semanas.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432206","ankiGuid":"u6]_tx-Pv5"},{"id":"anki-ginecologia-ulceras-genitais-7d064316e4368e78","number":"0232w","sourceNumber":"0232w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 27 anos se consultou por apresentar a lesão vaginal dolorosa reproduzida abaixo.\n\nAssinale a alternativa que contempla, na sequência, o provável diagnóstico, o agente etiológico e o tratamento indicado:","options":{"A":"Donovanose; Haemophilus ducreyi; amoxicilina.","B":"Donovanose; Chlamydia trachomatis; doxiciclina.","C":"Sífilis; Treponema pallidum; penicilina.","D":"Cancro mole; Klebsiella granulomatis; doxiciclina.","E":"Cancro mole; Haemophilus ducreyi; ceftriaxona."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":["question_bank/media/ginecologia-ulceras-genitais/paste-2889e906a55a3cce7ffe4eee897f82c2b7a08f72.png"],"optionImages":{},"commentImages":[],"comment":"Lesão vaginal dolorosa (conforme a imagem) — o padrão de dor aponta pro cancro mole, causado pelo Haemophilus ducreyi, tratado com ceftriaxona.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432207","ankiGuid":"g$Fx_8+W!["},{"id":"anki-ginecologia-ulceras-genitais-f42a06545f07522a","number":"0233w","sourceNumber":"0233w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"A doença infecto-contagiosa cujo diagnóstico se faz pela intradermorreação de Frei e que para o tratamento usamos Eritromicina, via oral, por 21 dias é:","options":{"A":"Gonorréia","B":"Sífilis","C":"Granuloma inguinal","D":"Linfogranuloma venéreo","E":"Tricomoníase"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O teste de Frei (uma reação na pele, hoje em desuso) e o tratamento com eritromicina por 21 dias eram usados classicamente pro linfogranuloma venéreo — uma infecção causada pela Chlamydia trachomatis que atinge principalmente os gânglios linfáticos da região genital.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432208","ankiGuid":"rwqGN(FWbm"},{"id":"anki-ginecologia-ulceras-genitais-0ccb22058add4dbf","number":"0234w","sourceNumber":"0234w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente 18 anos, com queixa de dor vulvar e perianal intensa há 7 dias. Ao exame apresentava vesículas agrupadas misturadas a pequenas úlceras, sem linfadenopatia inguinal dolorosa. Refere ser este um primeiro episódio. Qual o provável diagnóstico e conduta?","options":{"A":"Sífilis. Solicitar VDRL e prescrever penicilina benzatina 2.400.000 UI IM dose única.","B":"Sífilis. Solicitar VDRL e prescrever penicilina benzatina 1.200.000 UI IM dose única.","C":"Herpes genital. Sugerir teste para HIV e outras DST e prescrever aciclovir 400 mg de 8/8h por 7 a 10 dias.","D":"Cancroide. Azitromicina 1 g dose única.","E":"Condilomatose. Imiquimode 5%."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Dor vulvar e perianal com vesículas agrupadas misturadas a pequenas úlceras, primeiro episódio, sem gânglios dolorosos na virilha — é o quadro clássico de herpes genital (primo-infecção). O tratamento é com aciclovir, e também vale aproveitar pra oferecer testagem pra HIV e outras ISTs, já que quem tem uma infecção sexualmente transmissível tem mais chance de ter outra junto.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432209","ankiGuid":"i-G~rZ]2Ve"},{"id":"anki-ginecologia-ulceras-genitais-4babab5babbd7757","number":"0235w","sourceNumber":"0235w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 24 anos, residente e procedente de Goiânia, apresenta há três dias ulceração vulvar dolorosa com adenopatia inguinal. Neste caso, considerando","options":{"A":"os dados epidemiológicos e clínicos, a hipótese mais provável é cancro mole.","B":"o período evolutivo da doença, o VDRL negativo exclui o cancro duro.","C":"a evolução aguda da ulceração, deve ser solicitada biópsia com exame histopatológico.","D":"a baixa sensibilidade do método de Tzanck, o resultado negativo não exclui herpes genital."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O teste de Tzanck (usado pra procurar sinais de herpes numa lâmina) tem uma sensibilidade baixa — ou seja, mesmo que dê negativo, isso não garante que não seja herpes, já que o exame pode simplesmente não pegar o vírus mesmo ele estando presente.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432210","ankiGuid":"lGaoBI.-oi"},{"id":"anki-ginecologia-ulceras-genitais-660614491bf929e9","number":"0236w","sourceNumber":"0236w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Mulher de 23 anos teve diagnóstico de herpes e, frente a este diagnóstico, é correto afirmar que:","options":{"A":"As lesões são recidivantes e múltiplas.","B":"A infecção primária determina imunidade.","C":"A vacina multivírus não é curativa, mas sim preventiva.","D":"As lesões são dolorosas, mas não são contagiosas.","E":"As lesões são indolores, mas muito contagiosas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O herpes genital é conhecido por causar lesões que voltam a aparecer com o tempo (recidivantes) e que costumam vir em grupos (múltiplas vesículas/úlceras juntas) — diferente de uma lesão única e isolada, como a da sífilis.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432211","ankiGuid":"nGV`LgjZA?"},{"id":"anki-ginecologia-ulceras-genitais-47a6a10e4de05288","number":"0237w","sourceNumber":"0237w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Mulher de 21 anos consultou com médica de sistema privado de saúde por apresentar há cinco dias duas feridas dolorosas no lado direito de lábios vulvares. Por estar menstruada foi solicitado bacterioscopia pelo Gram das lesões vulvares. Por estar a médica, que lhe fez o primeiro atendimento, viajando, a paciente lhe procurou para apresentar o resultado do exame. A bacterioscopia descreve bacilos Gram-negativos compatíveis com H. ducrey. Queixou-se que há três dias percebe corrimento amarelado, fétido e não acompanhado por sintomas vaginais e urinários. Última menstruação finalizou há cinco dias e não utiliza nenhum tipo de método contraceptivo. Ao exame de genitais externos observam-se duas ulcerações rasas medindo cerca de 1 cm cada, com exsudato purulento em seu interior e à palpação bordos amolecidos e dolorosos. Ao toque ginecológico nenhuma alteração percebida. Ao exame especular observou-se conteúdo vaginal amarelado, cobrindo parcialmente o colo uterino. O teste de Whiff foi positivo e o pH vaginal 5,0. Após limpeza da cavidade vaginal com ácido acético 2% observou-se drenagem de secreção amarelada proveniente do canal cervical. Com os dados disponíveis estão corretas as seguintes afirmativas: I – É frequente a associação da ulceração vulvar que esta paciente apresenta com o Treponema pallidum, constituindo o cancro misto de Rollet; II – Indica-se a solicitação de VDRL; III – Doenças como herpes genital, cancro duro e doença de Behçet cursam com ulcerações vulvares dolorosas; IV – Além das lesões vulvares esta paciente apresenta vaginose bacteriana e cervicite mucopurulenta; V – O tratamento indicado é ceftriaxona 500 mg IM em dose única, azitromicina 1 g via oral em dose única e secnidazol 2 g via oral em dose única. A seguinte alternativa contempla o enunciado desta questão:","options":{"A":"I e III apenas.","B":"I, III e IV.","C":"I, IV e V.","D":"II, III e V.","E":"III, IV e V."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Vamos por item: a associação de cancro mole com sífilis no mesmo local (cancro misto de Rollet) realmente existe e é descrita na literatura (I, verdadeiro). Como há uma úlcera genital, pedir VDRL pra descartar sífilis associada também faz sentido (II). Mas dizer que sífilis (cancro duro) causa úlceras DOLOROSAS está errado — ela é classicamente indolor, diferente do herpes e da doença de Behçet, que sim doem (III, considerado errado nessa questão). Os achados do exame (teste de Whiff positivo, corrimento do colo) realmente indicam vaginose bacteriana e cervicite associadas (IV, verdadeiro). E o tratamento com ceftriaxona (pra gonococo), azitromicina (pra clamídia) e secnidazol (pra vaginose) cobre bem esse conjunto de infecções (V, verdadeiro).","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432212","ankiGuid":"C2caSCZXd4"},{"id":"anki-ginecologia-ulceras-genitais-85af09017d315a4b","number":"0238w","sourceNumber":"0238w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Em relação ao diagnóstico das úlceras genitais, é CORRETO afirmar que:","options":{"A":"Deve ser realizado em centros especializados, visto que o conhecimento exato da morfologia da úlcera tem alta especificidade e deve orientar o tratamento etiológico.","B":"Na sífilis, as úlceras, em geral, são múltiplas, com fundo limpo e linfadenopatia inguinal indolor.","C":"As úlceras do cancroide são habitualmente múltiplas, podendo ser únicas, acometendo, mais frequentemente, o sexo feminino.","D":"No linfogranuloma venéreo, a úlcera, frequentemente, não é mais visualizada no momento da consulta, sendo a linfadenopatia com fistulização múltipla um aspecto característico.","E":"Nas lesões herpéticas mucosas, a fase das vesículas costuma ser mais duradoura que nas lesões cutâneas, sendo, portanto, visualizadas, mais frequentemente, ao exame clínico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"No linfogranuloma venéreo, é comum que, na hora da consulta, a úlcera inicial já tenha desaparecido sozinha (ela costuma ser pequena e passar despercebida) — o que chama mais atenção é a fase seguinte, com os gânglios da virilha bem inchados, podendo até formar múltiplos pontos de drenagem de pus (fistulização), um achado bem característico dessa doença.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432213","ankiGuid":"EPk1#VUidt"},{"id":"anki-ginecologia-ulceras-genitais-b61fd5eee9adda1e","number":"0239w","sourceNumber":"0239w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 52 anos, G2P2, menopausada há 5 anos, apresenta úlcera genital dolorosa, de fundo necrótico, com hiperemia local. Tem histórico de apresentar lesões orais como \"aftas\" (sic) recorrentemente. O clínico geral solicitou alguns exames complementares, a saber: VDRL (negativo), HIV (negativo), Gram e citologia da lesão (inespecífico). O diagnóstico mais provável é:","options":{"A":"Cancro mole.","B":"Sífilis primária.","C":"Herpes genital.","D":"Líquen escleroatrófico.","E":"Doença de Behçet."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera genital dolorosa associada a 'aftas' recorrentes na boca, com todos os exames infecciosos negativos (sífilis, HIV, bacterioscopia) — esse padrão de úlceras recorrentes tanto na boca quanto na genital, sem causa infecciosa encontrada, é bem sugestivo da doença de Behçet, uma doença inflamatória (não infecciosa) que também pode afetar os olhos e a pele.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432214","ankiGuid":"DW3ogWvIuy"},{"id":"anki-ginecologia-ulceras-genitais-be57763a1238e1ba","number":"0240w","sourceNumber":"0240w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente de 28 anos, sexualmente ativa, chega a UABSF com uma ulceração de borda plana ou hipertrófica, bem delimitada, com fundo granuloso, de aspecto vermelho vivo e de sangramento fácil na região perianal há quatro semanas. A lesão sempre foi dessa forma, não passando pelo estágio de vesícula. O micro-organismo isolado da lesão foi a Klebsiella granulomatis. Dessa forma, o tratamento de primeira escolha seria:","options":{"A":"Sulfametoxazol + trimetoprima, 2 comprimidos VO, 2x/dia, por 1 semana.","B":"Doxiciclina 100 mg, 1 comprimido VO, 2x/dia por, pelo menos, 21 dias ou até o desaparecimento completo da lesão.","C":"Azitromicina 500 mg, 2 comprimidos VO, dose única.","D":"Ciprofloxacino 500 mg, 1 comprimido VO, 2x/dia, por 3 dias."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Úlcera indolor, bem definida, com fundo granuloso vermelho vivo que sangra fácil, sem nunca ter passado por uma fase de vesícula, com a bactéria Klebsiella granulomatis identificada — é a donovanose. O tratamento de primeira escolha é a doxiciclina, tomada por pelo menos 21 dias (ou até a lesão sumir completamente).","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432215","ankiGuid":"xc,s}`v>OZ"},{"id":"anki-ginecologia-ulceras-genitais-ffda19b6dd966e66","number":"0241w","sourceNumber":"0241w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"Paciente do sexo masculino, 26 anos, atendido no ambulatório de Clínica Médica, encaminhado pelo oftalmologista por apresentar panuveíte bilateral. Queixava-se também de ulcerações aftosas recorrentes, apresentando no momento do exame lesões orais dolorosas, rasas e pequenas de base necrótica central amarelada, além de lesão genital única, indolor, em escroto. Apresentava também lesões cutâneas sugestivas de pioderma gangrenoso. O teste de patergia foi positivo em 48h. Dentre as opções listadas abaixo, a que mais se relaciona às manifestações apresentadas por este paciente é:","options":{"A":"Sífilis primária;","B":"Cancro mole;","C":"Lesão herpética;","D":"Sarcoidose;","E":"Síndrome de Behçet."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"Uveíte nos dois olhos, aftas orais recorrentes, úlcera genital indolor, lesões de pele parecidas com pioderma gangrenoso e teste de patergia positivo (uma reação de pele exagerada a uma picadinha de agulha) — esse conjunto de achados é bem característico da síndrome de Behçet, uma doença inflamatória que afeta vasos sanguíneos em várias partes do corpo.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432216","ankiGuid":"F)+dN]w<y&"},{"id":"anki-ginecologia-ulceras-genitais-77215f906a170fb4","number":"0242w","sourceNumber":"0242w","collectionBlock":"anki:ginecologia-ulceras-genitais","collectionLabel":"Anki · Úlceras Genitais","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Úlceras Genitais","subtopic":"","stem":"O diagnóstico laboratorial faz-se pela intrademorreação de Frei e o tratamento com eritromicina, via oral, durante 21 dias. A descrição sugere a seguinte patologia:","options":{"A":"gonorreia","B":"sífilis","C":"toxoplasmose","D":"granuloma inguinal","E":"linfogranuloma venéreo"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Úlceras Genitais","images":[],"optionImages":{},"commentImages":[],"comment":"O teste de Frei e o tratamento prolongado com eritromicina (21 dias) eram usados classicamente pro diagnóstico e tratamento do linfogranuloma venéreo, causado pela Chlamydia trachomatis.","tags":["Ginecologia e Obstetrícia","Úlceras Genitais","Anki"],"ankiNoteId":"1780580432217","ankiGuid":"k&ss.BN-BK"}]};
